{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260921T220951Z/cell-M3dZDI/src/address.js","content":"/**
 * Cell address parsing and ordering.
 *
 * An address is one or two letters naming a column and one to three digits
 * naming a row of at least 1. Columns are numbered A=1 .. Z=26, AA=27 ..
 * ZZ=702 (bijective base-26), which gives a total ordering that matches
 * ascending column then ascending row.
 */

const ADDRESS_RE = /^([A-Za-z]{1,2})([0-9]{1,3})$/

/**
 * Parses text as a cell address, upper-casing it as it is read.
 *
 * Returns null when the text is not shaped like an address at all (not
 * letters-then-digits), or an object `{ text, col, row }` describing the
 * address otherwise. `col`/`row` may be out of the addressable range; the
 * caller decides what that means (invalid address vs. #REF!).
 */
export function parseAddressShape(text) {
  const m = ADDRESS_RE.exec(text)
  if (!m) return null
  const letters = m[1].toUpperCase()
  const row = Number(m[2])
  let col = 0
  for (const ch of letters) col = col * 26 + (ch.charCodeAt(0) - 64)
  return { text: letters + m[2], letters, col, row }
}

/** True when the address shape names a column/row inside the addressable range. */
export function inRange(shape) {
  return shape.row >= 1 && shape.row <= 999 && shape.col >= 1 && shape.col <= 702
}

/** Parses and range-checks an address, returning null when either check fails. */
export function parseAddress(text) {
  const shape = parseAddressShape(text)
  if (!shape || !inRange(shape)) return null
  return shape
}

/** Comparator for addresses: ascending column, then ascending row. */
export function compareAddresses(a, b) {
  if (a.col !== b.col) return a.col - b.col
  return a.row - b.row
}
"}

