{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260921T220951Z/cell-M3dZDI/src/sheet.js","content":"/**
 * Parses raw sheet text into an address -> content map.
 */

import { parseAddress } from './address.js'

/** Thrown for a malformed line; carries the message the CLI writes to stderr. */
export class SheetError extends Error {}

/**
 * Splits `text` on newlines (dropping the empty tail a trailing newline
 * leaves), and parses each surviving line into an address/content pair.
 *
 * Returns a Map from address text (e.g. "A1") to its raw content string, in
 * first-declaration order (later reinserted in print order by callers).
 */
export function parseSheet(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cells = new Map()
  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const raw = lines[i]
    const stripped = raw.replace(/^[ \t]+/, '')
    if (stripped === '' || stripped.startsWith('#')) continue

    const m = /^(\S+)([ \t]*)/.exec(stripped)
    const addrText = m[1]
    let rest = stripped.slice(addrText.length)
    if (rest.length > 0) rest = rest.replace(/^[ \t]+/, '')

    const addr = parseAddress(addrText)
    if (!addr) throw new SheetError(`error: line ${lineNo}: invalid cell address ${addrText}\n`)
    if (cells.has(addr.text)) {
      throw new SheetError(`error: line ${lineNo}: cell ${addr.text} is declared twice\n`)
    }
    cells.set(addr.text, rest)
  }
  return cells
}
"}

