{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260921T220951Z/cell-M3dZDI/src/lexer.js","content":"/**
 * Tokenizer for formula bodies (the text after the leading `=`).
 */

const OPERATORS = ['<=', '<>', '>=', '^', '*', '/', '+', '-', '=', '<', '>']

/**
 * Splits `body` into tokens. Throws nothing; an unrecognized character
 * simply yields no further tokens (the parser then sees a premature end of
 * input, or a trailing token that doesn't fit, and reports a parse failure).
 */
export function tokenize(body) {
  const tokens = []
  let i = 0
  const n = body.length
  while (i < n) {
    const ch = body[i]
    if (ch === ' ' || ch === '\t') {
      i++
      continue
    }
    if (ch >= '0' && ch <= '9') {
      let j = i + 1
      while (j < n && body[j] >= '0' && body[j] <= '9') j++
      if (body[j] === '.' && body[j + 1] >= '0' && body[j + 1] <= '9') {
        j++
        while (j < n && body[j] >= '0' && body[j] <= '9') j++
      }
      tokens.push({ type: 'NUMBER', value: body.slice(i, j) })
      i = j
      continue
    }
    if (/[A-Za-z]/.test(ch)) {
      let j = i + 1
      while (j < n && /[A-Za-z]/.test(body[j])) j++
      while (j < n && body[j] >= '0' && body[j] <= '9') j++
      tokens.push({ type: 'IDENT', value: body.slice(i, j) })
      i = j
      continue
    }
    if (ch === '(') {
      tokens.push({ type: 'LPAREN' })
      i++
      continue
    }
    if (ch === ')') {
      tokens.push({ type: 'RPAREN' })
      i++
      continue
    }
    if (ch === ',') {
      tokens.push({ type: 'COMMA' })
      i++
      continue
    }
    if (ch === ':') {
      tokens.push({ type: 'COLON' })
      i++
      continue
    }
    const op = OPERATORS.find((o) => body.startsWith(o, i))
    if (op) {
      tokens.push({ type: 'OP', value: op })
      i += op.length
      continue
    }
    tokens.push({ type: 'INVALID', value: ch })
    i++
  }
  return tokens
}
"}

