/** Builds canonical address text (e.g. "AA12") from a column/row pair. */
export function formatAddress(col, row) {
  let c = col
  let letters = ''
  while (c > 0) {
    const rem = (c - 1) % 26
    letters = String.fromCharCode(65 + rem) + letters
    c = Math.floor((c - 1) / 26)
  }
  return letters + String(row)
}

