 * The four value kinds a cell can hold, plus the error tokens.
 */

export const ERROR_TOKENS = new Set(['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!'])

export function mkNumber(value) {
  return { type: 'number', value }
}
export function mkText(value) {
  return { type: 'text', value }
}
export function mkBoolean(value) {
  return { type: 'boolean', value }
}
export function mkError(token) {
  return { type: 'error', value: token }
}

export const ERR_DIV0 = mkError('#DIV/0!')
export const ERR_REF = mkError('#REF!')
export const ERR_VALUE = mkError('#VALUE!')
export const ERR_CYCLE = mkError('#CYCLE!')
export const ERR_NAME = mkError('#NAME?')
export const ERR_ERR = mkError('#ERR!')

/**
 * Reads a value as a number in an arithmetic position: a number stays, a
 * boolean becomes 1 or 0, text becomes #VALUE!, and an error passes through
 * unchanged. Returns a plain JS number or an error value.
 */
export function asNumber(value) {
  if (value.type === 'number') return value.value
  if (value.type === 'boolean') return value.value ? 1 : 0
  if (value.type === 'error') return value
  return ERR_VALUE
}

const KIND_RANK = { number: 0, text: 1, boolean: 2 }

/**
 * Three-way comparison between two non-error values: numbers compare
 * numerically, text compares by code point, booleans compare false below
 * true, and across kinds every number sorts below every text which sorts
 * below every boolean.
 */
export function compareValues(a, b) {
  if (a.type !== b.type) return KIND_RANK[a.type] - KIND_RANK[b.type]
  if (a.type === 'number') return a.value - b.value
  if (a.type === 'text') return a.value < b.value ? -1 : a.value > b.value ? 1 : 0
  return (a.value ? 1 : 0) - (b.value ? 1 : 0)
}
"}

