  switch (value.type) {
    case 'number':
      return formatNumber(value.value)
    case 'error':
      return value.value
    case 'boolean':
      return value.value ? 'TRUE' : 'FALSE'
    case 'text':
      return value.value
    default:
      throw new Error('unreachable value kind')
  }
}
"}

