export class Evaluator {
  constructor(cells) {
    this.cells = cells
    this.astCache = new Map()
    this.valueCache = new Map()
    this.stack = []
  }

  getAst(addr) {
    if (this.astCache.has(addr)) return this.astCache.get(addr)
    const content = this.cells.get(addr)
    const ast = content.startsWith('=') ? parseFormula(content.slice(1)) : null
    this.astCache.set(addr, ast)
    return ast
  }

  getValue(addr) {
    if (this.valueCache.has(addr)) return this.valueCache.get(addr)

    const idx = this.stack.indexOf(addr)
    if (idx !== -1) {
      for (let k = idx; k < this.stack.length; k++) this.valueCache.set(this.stack[k], ERR_CYCLE)
      return ERR_CYCLE
    }

    this.stack.push(addr)
    let result
    if (!this.cells.has(addr)) {
      result = mkNumber(0)
    } else {
      const content = this.cells.get(addr)
      if (content.startsWith('=')) {
        const ast = this.getAst(addr)
        result = ast ? this.evalNode(ast) : ERR_ERR
      } else {
        result = parseLiteral(content)
      }
    }
    this.stack.pop()

    if (this.valueCache.has(addr)) return this.valueCache.get(addr)
    this.valueCache.set(addr, result)
    return result
  }

  evalNode(node) {
