    if (left.type === 'error') return left
    const right = this.evalNode(node.right)
    if (right.type === 'error') return right

    if (node.op in COMPARISON_OPS) {
      const cmp = compareValues(left, right)
      return mkBoolean(COMPARISON_OPS[node.op](cmp))
    }

    const ln = asNumber(left)
    if (typeof ln !== 'number') return ln
    const rn = asNumber(right)
