    const arity = AGGREGATE_ARITY[node.name]
    if (!arity) return ERR_NAME
    if (node.args.length < arity.min || node.args.length > arity.max) return ERR_ERR

    if (node.name === 'IF') return this.evalIf(node)

    const flat = this.flattenArgs(node.args)

    if (node.name === 'COUNT') {
      for (const v of flat) if (v.type === 'error') return v
      return mkNumber(flat.filter((v) => v.type === 'number').length)
    }

    const nums = []
    for (const v of flat) {
      const n = asNumber(v)
      if (typeof n !== 'number') return n
      nums.push(n)
    }

    switch (node.name) {
      case 'SUM': {
        const sum = nums.reduce((a, b) => a + b, 0)
