 * Evaluates a sheet's cells into values, with cycle detection.
 */

import { parseAddress, rangeCells } from './address.js'
import { parseFormula } from './parser.js'
import { parseLiteral } from './literal.js'
import { asNumber, compareValues, mkNumber, mkBoolean, ERR_DIV0, ERR_REF, ERR_VALUE, ERR_NAME, ERR_ERR, ERR_CYCLE } from './values.js'

const COMPARISON_OPS = {
  '=': (c) => c === 0,
  '<>': (c) => c !== 0,
  '<': (c) => c < 0,
  '<=': (c) => c <= 0,
  '>': (c) => c > 0,
  '>=': (c) => c >= 0,
}

const AGGREGATE_ARITY = {
  SUM: { min: 1, max: Infinity },
  MIN: { min: 1, max: Infinity },
  MAX: { min: 1, max: Infinity },
  COUNT: { min: 1, max: Infinity },
  AVG: { min: 1, max: Infinity },
  ABS: { min: 1, max: 1 },
  IF: { min: 3, max: 3 },
}

/** Evaluates every declared cell in `cells` (address text -> raw content). */
export class Evaluator {
  constructor(cells) {
    this.cells = cells
    this.astCache = new Map()
    this.valueCache = new Map()
    this.stack = []
  }

  getAst(addr) {
    if (this.astCache.has(addr)) return this.astCache.get(addr)
    const content = this.cells.get(addr)
    const ast = content.startsWith('=') ? parseFormula(content.slice(1)) : null
    this.astCache.set(addr, ast)
    return ast
  }

  getValue(addr) {
    if (this.valueCache.has(addr)) return this.valueCache.get(addr)

    const idx = this.stack.indexOf(addr)
    if (idx !== -1) {
      for (let k = idx; k < this.stack.length; k++) this.valueCache.set(this.stack[k], ERR_CYCLE)
      return ERR_CYCLE
    }

    this.stack.push(addr)
    let result
    if (!this.cells.has(addr)) {
      result = mkNumber(0)
    } else {
      const content = this.cells.get(addr)
      if (content.startsWith('=')) {
        const ast = this.getAst(addr)
        result = ast ? this.evalNode(ast) : ERR_ERR
      } else {
        result = parseLiteral(content)
      }
    }
    this.stack.pop()

    if (this.valueCache.has(addr)) return this.valueCache.get(addr)
    this.valueCache.set(addr, result)
    return result
  }

  evalNode(node) {
    switch (node.type) {
      case 'num':
        return mkNumber(node.value)
      case 'bool':
        return mkBoolean(node.value)
      case 'address':
        return this.evalAddress(node)
      case 'range':
        // A range is only meaningful directly as a function argument; used
        // anywhere else it is a grammar-accepted but invalid expression.
        return ERR_ERR
      case 'unary':
        return this.evalUnary(node)
      case 'bin':
        return this.evalBin(node)
      case 'call':
        return this.evalCall(node)
      default:
        throw new Error('unreachable node type')
    }
  }

  evalAddress(node) {
    const shape = parseAddress(node.text)
    if (!shape) return ERR_REF
    return this.getValue(shape.text)
  }

  evalUnary(node) {
    const operand = this.evalNode(node.expr)
    if (operand.type === 'error') return operand
    const n = asNumber(operand)
    if (typeof n !== 'number') return n
    const result = node.op === '-' ? -n : n
    return Number.isFinite(result) ? mkNumber(result) : ERR_DIV0
  }

  evalBin(node) {
    const left = this.evalNode(node.left)
    if (left.type === 'error') return left
    const right = this.evalNode(node.right)
    if (right.type === 'error') return right

    if (node.op in COMPARISON_OPS) {
      const cmp = compareValues(left, right)
      return mkBoolean(COMPARISON_OPS[node.op](cmp))
    }

    const ln = asNumber(left)
    if (typeof ln !== 'number') return ln
    const rn = asNumber(right)
    if (typeof rn !== 'number') return rn

    let result
    switch (node.op) {
      case '+':
        result = ln + rn
        break
      case '-':
        result = ln - rn
        break
      case '*':
        result = ln * rn
        break
      case '/':
        if (rn === 0) return ERR_DIV0
        result = ln / rn
        break
      case '^':
        result = Math.pow(ln, rn)
        break
      default:
        throw new Error('unreachable operator')
    }
    return Number.isFinite(result) ? mkNumber(result) : ERR_DIV0
  }

  evalCall(node) {
    const arity = AGGREGATE_ARITY[node.name]
    if (!arity) return ERR_NAME
    if (node.args.length < arity.min || node.args.length > arity.max) return ERR_ERR

    if (node.name === 'IF') return this.evalIf(node)

    const flat = this.flattenArgs(node.args)

    if (node.name === 'COUNT') {
      for (const v of flat) if (v.type === 'error') return v
      return mkNumber(flat.filter((v) => v.type === 'number').length)
    }

    const nums = []
    for (const v of flat) {
      const n = asNumber(v)
      if (typeof n !== 'number') return n
      nums.push(n)
    }

    switch (node.name) {
      case 'SUM': {
        const sum = nums.reduce((a, b) => a + b, 0)
        return Number.isFinite(sum) ? mkNumber(sum) : ERR_DIV0
      }
      case 'MIN':
        return mkNumber(Math.min(...nums))
      case 'MAX':
        return mkNumber(Math.max(...nums))
