        const avg = nums.reduce((a, b) => a + b, 0) / nums.length
        return Number.isFinite(avg) ? mkNumber(avg) : ERR_DIV0
      }
      case 'ABS': {
        const abs = Math.abs(nums[0])
        return Number.isFinite(abs) ? mkNumber(abs) : ERR_DIV0
      }
