    }
  }

  evalIf(node) {
    const cond = this.evalNode(node.args[0])
    if (cond.type === 'error') return cond
    let truthy
    if (cond.type === 'boolean') truthy = cond.value
    else if (cond.type === 'number') truthy = cond.value !== 0
    else return ERR_VALUE
    return this.evalNode(node.args[truthy ? 1 : 2])
  }

  // Flattens call arguments left to right into a value list, expanding any
  // argument that is directly a range into the values of every cell it
  // covers, in ascending column then ascending row order.
  flattenArgs(argNodes) {
    const flat = []
    for (const arg of argNodes) {
      if (arg.type === 'range') {
        const cells = rangeCells(arg.from, arg.to)
        if (!cells) {
          flat.push(ERR_REF)
        } else {
          for (const addr of cells) flat.push(this.getValue(addr))
        }
      } else {
        flat.push(this.evalNode(arg))
      }
    }
    return flat
  }
}
