 * Lists the cells a formula names directly, for `deps` mode. This is purely
 * syntactic: it walks the AST without evaluating it, so every referenced
 * cell is listed regardless of which branch a taken `IF` would pick, or
 * whether the reference is otherwise semantically valid.
 */

import { parseAddress, rangeCells, compareAddresses } from './address.js'
import { parseFormula } from './parser.js'

function walk(node, addrs) {
  switch (node.type) {
    case 'num':
    case 'bool':
      return
    case 'address': {
      const shape = parseAddress(node.text)
      if (shape) addrs.set(shape.text, shape)
      return
    }
    case 'range': {
      const cells = rangeCells(node.from, node.to)
      if (cells) for (const addr of cells) addrs.set(addr, parseAddress(addr))
      return
    }
    case 'unary':
      walk(node.expr, addrs)
      return
    case 'bin':
      walk(node.left, addrs)
      walk(node.right, addrs)
      return
    case 'call':
      for (const arg of node.args) walk(arg, addrs)
      return
    default:
      throw new Error('unreachable node type')
  }
}

/**
 * Returns the distinct addresses `content` names directly, ranges expanded,
 * ordered by ascending column then ascending row. A literal, or a formula
 * the grammar rejects, names none.
 */
export function formulaDeps(content) {
  if (!content.startsWith('=')) return []
  const ast = parseFormula(content.slice(1))
  if (!ast) return []
  const addrs = new Map()
  walk(ast, addrs)
  return [...addrs.values()].sort(compareAddresses).map((shape) => shape.text)
}
"}

