/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import fs from 'node:fs'
import { parseSheet, SheetError } from './sheet.js'
import { compareAddresses, parseAddress } from './address.js'
import { Evaluator } from './evaluate.js'
import { formatValue } from './format.js'
import { formulaDeps } from './deps.js'

function fail(message) {
  process.stderr.write(message)
  process.exit(2)
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'values' && mode !== 'deps')) {
    fail('error: usage: cli.js values|deps\n')
    return
  }

  const input = fs.readFileSync(0, 'utf8')

  let cells
  try {
    cells = parseSheet(input)
  } catch (e) {
    if (e instanceof SheetError) {
      fail(e.message)
      return
    }
    throw e
  }

  const ordered = [...cells.keys()].map((addr) => parseAddress(addr)).sort(compareAddresses)

  const lines = []
  if (mode === 'values') {
    const evaluator = new Evaluator(cells)
    for (const shape of ordered) {
      lines.push(`${shape.text}=${formatValue(evaluator.getValue(shape.text))}\n`)
    }
  } else {
    for (const shape of ordered) {
      const deps = formulaDeps(cells.get(shape.text))
      lines.push(`${shape.text}:${deps.map((d) => ' ' + d).join('')}\n`)
    }
  }

  process.stdout.write(lines.join(''))
}

main()
"}

